import {esc} from './html.js';
import {mondayOf,plusDays,minText,dateText} from '../domain/date.js';
import {tasksOn,progress,summarize} from '../domain/study.js';
import {views,period,within,pageOf} from './view-state.js';
const $=id=>document.getElementById(id);
const button=(attribute,value,label,target,extra='')=>`<button class="button quiet" ${attribute}="${esc(value)}" aria-label="${esc(target+'：'+label)}" ${extra}>${label}</button>`;
export function planRows(plans,items){const names=new Map(items.map(i=>[i.id,i.title]));return plans.map(s=>{const title=names.get(s.itemId)||'項目不明';if(s.archived){const blocked=items.find(i=>i.id===s.itemId)?.archived;return `<article class="plan-row archived-row"><div><strong>${esc(title)}</strong><small>${esc(s.date)} ・ ${s.required?'必須':'任意'} ・ ${s.status==='completed'?'完了済み':'未完了'}</small></div><span class="pill">予定 ${s.minutes}分</span><div>${blocked?'<span class="muted small">先に学習項目を復帰してください</span>':button('data-unarchive-plan',s.id,'予定を復帰',title)}</div></article>`;}return `<article class="plan-row"><label class="task ${s.status==='completed'?'done':''}"><input type="checkbox" data-task="${esc(s.id)}" aria-label="${esc(s.date+' '+title+'の完了')}" ${s.status==='completed'?'checked':''}><span><strong>${esc(title)}</strong><small>${esc(s.date)} ・ ${s.required?'必須':'任意'}</small></span></label><span class="pill">予定 ${s.minutes}分</span><div class="row-actions">${button('data-record-schedule',s.id,'実績を記録',title,'data-priority="record"')}${button('data-edit-task',s.id,'予定を編集',title)}</div></article>`;}).join('')||'<p class="empty-guidance">この条件の予定はありません。「＋ 予定」で追加できます。</p>';}
export function recordRows(records){return records.map(r=>`<article class="recent-row"><time>${esc(r.date)}</time><div><strong>${esc(r.subject)}</strong>${r.note?`<p class="muted small">${esc(r.note)}</p>`:''}</div><span class="pill">実績 ${minText(r.minutes)}</span>${button('data-edit-record',r.id,'実績を編集',r.date+' '+r.subject)}</article>`).join('')||'<p class="empty-guidance">この条件の実績はありません。学習した内容を記録しましょう。</p>';}
function pager(list,group,state){const p=pageOf(list,state);return {...p,html:`<div class="pagination"><span>${p.total}件（${p.total?p.page*25+1:0}–${Math.min((p.page+1)*25,p.total)}件を表示） ・ ${p.page+1} / ${p.pages}ページ（25件ずつ）</span><div>${button('data-page-step',group,'前へ',views[group],`data-step="-1" ${p.page===0?'disabled':''}`)}${button('data-page-step',group,'次へ',views[group],`data-step="1" ${p.page===p.pages-1?'disabled':''}`)}</div></div>`};}
function week(project,start,selected){return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const date=plusDays(start,i),tasks=tasksOn(project,date),p=progress(tasks);return `<button class="week-day ${date===selected?'selected':''}" data-date="${date}" aria-label="${date}の予定を見る"><span>${Number(date.slice(8))}</span><small>${'月火水木金土日'[i]}</small><strong>${tasks.reduce((sum,s)=>sum+s.minutes,0)}分</strong><small>${p.completed}/${p.total}完了</small></button>`;}).join('')}</div>`;}
function stats(records,limit=Infinity){const s=summarize(records);return `<div class="stats-total"><strong>${minText(s.minutes)}</strong><span class="muted">${s.days}日間の実績</span></div>`+s.subjects.slice(0,limit).map(x=>`<div class="stat"><div><span>${esc(x.name)}</span><strong>${x.minutes}分</strong></div><progress aria-label="${esc(x.name)}の学習時間" value="${x.minutes}" max="${Math.max(1,s.minutes)}"></progress></div>`).join('');}
export function renderViews(data,prefs,state,today,available){
 const p=data?.project,itemNames=new Map((p?.items||[]).map(i=>[i.id,i.title]));const empty='<p class="empty-guidance">先にプロジェクトを作成してください。</p>';
 $('onboarding').innerHTML=!p?`<section class="card onboarding"><h2>${available?'空の学習環境から始めよう':'保存領域を読み込めませんでした'}</h2><p>${available?'学ぶ内容と日付を決めて、自分の学習を始めましょう。':'既存データは初期化していません。「最新データを確認」で再試行してください。'}</p><button class="button primary" data-create="project" ${available?'':'disabled'}>1. プロジェクトを作る</button><button class="button" data-view="data">バックアップから復元</button></section>`:!p.items.some(i=>!i.archived)?'<section class="card onboarding"><h2>次は、学ぶ内容を登録しよう</h2><button class="button primary" data-create="item">2. 学習項目を追加</button></section>':!p.schedules.some(s=>!s.archived)?'<section class="card onboarding"><h2>学習する日を決めよう</h2><button class="button primary" data-create="task">3. 学習予定を追加</button></section>':'';
 if(!p){for(const id of ['plans-list','items-list','records-list','analysis-results'])$(id).innerHTML=empty;$('dashboard').innerHTML='';$('hidden-cards').innerHTML='';$('plan-week').innerHTML='';return;}
 const card=(id,body)=>`<section id="card-${id}" class="card card-${id}" ${prefs.visibility[id]?'':'hidden'}>${body}</section>`;
 const tasks=tasksOn(p,today),done=progress(tasks),records=data.records.filter(r=>r.date===today),start=mondayOf(today),weekRecords=data.records.filter(r=>within(r.date,{from:start,to:plusDays(start,6)}));
 const sorted=[...data.records].sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));
 $('dashboard').innerHTML=card('today',`<div class="section-heading"><div><p class="eyebrow">今日の予定</p><h2>${esc(p.name)}</h2></div><span class="today-goal">${esc(p.goal||'自分のペースで学習')}</span></div><div class="today-metrics"><span><strong>${done.completed} / ${done.total}</strong> 必須予定の完了</span><span><strong>${tasks.reduce((n,s)=>n+s.minutes,0)}分</strong> 予定時間</span><span><strong>${summarize(records).minutes}分</strong> 実績時間</span></div><div class="today-plans">${planRows(tasks.slice(0,10),p.items)}</div>${tasks.length>10?'<button class="button" data-view="plans">すべての予定を学習計画で見る</button>':''}`)
 +card('week',`<div class="section-heading"><h2>今週の計画</h2><button class="button quiet" data-view="plans">計画を見る →</button></div><p class="muted small">${start} 〜 ${plusDays(start,6)} ・ 時間は予定、完了数は必須予定</p>${week(p,start,today)}`)
 +card('stats',`<div class="section-heading"><h2>今週の学習時間</h2><button class="button quiet" data-view="analysis">分析へ →</button></div>${stats(weekRecords,3)}<p class="muted small">実績の「学習した内容」別に集計</p>`)
 +card('recent',`<div class="section-heading"><h2>最近の記録</h2><button class="button quiet" data-view="records">すべて見る（${data.records.length}件）</button></div><div class="recent-list">${recordRows(sorted.slice(0,5))}</div>`);
 const names={today:'今日の学習',week:'今週の計画',stats:'学習時間',recent:'最近の記録'};$('hidden-cards').innerHTML=Object.entries(names).filter(([id])=>!prefs.visibility[id]).map(([id,name])=>`<button class="button quiet" data-restore="${id}">${name}を再表示</button>`).join('');
 try{const range=period(state.plans.mode,state.plans.from,state.plans.to,today);const plans=p.schedules.filter(s=>s.archived===(state.plans.state==='archived')&&within(s.date,range)&&itemNames.get(s.itemId)?.toLocaleLowerCase().includes(state.plans.query.toLocaleLowerCase())).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)),page=pager(plans,'plans',state.plans);$('plan-week').innerHTML=state.plans.mode==='week'&&state.plans.state!=='archived'?week(p,range.from,state.plans.from):'';$('plans-list').innerHTML=`<p class="muted">${state.plans.state==='archived'?'アーカイブ済み予定（実績は保持）。見つからない場合は「全期間」で確認してください。 ':''}${range.from||'開始指定なし'} 〜 ${range.to||'終了指定なし'}</p>`+page.html+planRows(page.rows,p.items);}catch(e){$('plan-week').innerHTML='';$('plans-list').innerHTML=`<p role="alert">${esc(e.message)}</p>`;}
 const counts=new Map();for(const s of p.schedules)if(!s.archived)counts.set(s.itemId,(counts.get(s.itemId)||0)+1);
 const items=p.items.filter(i=>i.archived===(state.items.state==='archived')&&i.title.toLocaleLowerCase().includes(state.items.query.toLocaleLowerCase()));const ip=pager(items,'items',state.items);
 $('items-list').innerHTML=ip.html+ip.rows.map(i=>`<article class="item-row"><div><strong>${esc(i.title)}</strong><small class="muted">有効な予定 ${counts.get(i.id)||0}件${i.archived?' ・ アーカイブ済み':''}</small></div>${i.archived?button('data-unarchive-item',i.id,'項目を復帰',i.title):`${button('data-edit-item',i.id,'項目を編集',i.title)}${button('data-plan-item',i.id,'予定に追加',i.title)}`}</article>`).join('')+(items.length?'':'<p class="empty-guidance">一致する学習項目はありません。</p>');
 const select=$('record-item');select.innerHTML='<option value="">すべての項目</option><option value="__none">関連付けなし</option>'+p.items.map(i=>`<option value="${esc(i.id)}">${esc(i.title)}${i.archived?'（アーカイブ）':''}</option>`).join('');select.value=state.records.itemId;if(select.value!==state.records.itemId){state.records.itemId='';select.value='';}
 const rf=state.records;if(rf.from&&rf.to&&rf.from>rf.to){$('records-list').innerHTML='<p role="alert">終了日は開始日以降を指定してください。</p>';}else{const rs=sorted.filter(r=>within(r.date,rf)&&(!rf.itemId||(rf.itemId==='__none'?r.itemId===null:r.itemId===rf.itemId))&&(r.subject+' '+r.note).toLocaleLowerCase().includes(rf.query.toLocaleLowerCase())),rp=pager(rs,'records',rf);$('records-list').innerHTML=rp.html+recordRows(rp.rows);}
 try{const a=state.analysis,range=period(a.mode,a.mode==='range'?a.from:today,a.to,today),rs=data.records.filter(r=>within(r.date,range)),sum=summarize(rs),sp=pager(sum.subjects,'analysis',a);$('analysis-results').innerHTML=`<h2>実績の学習時間</h2><p class="muted">期間：${range.from||'開始指定なし'} 〜 ${range.to||'終了指定なし'}<br>集計単位：実績の「学習した内容」の文字列。表記が異なる場合は別集計です。</p><div class="stats-total"><strong>${minText(sum.minutes)}</strong><span>${sum.days}日・${rs.length}件の実績</span></div>`+(rs.length?sp.html+sp.rows.map(x=>`<div class="stat"><div><span>${esc(x.name)}</span><strong>${x.minutes}分</strong></div><progress value="${x.minutes}" max="${Math.max(sum.minutes,1)}" aria-label="${esc(x.name)}の学習時間"></progress></div>`).join(''):'<p class="empty-guidance">この期間の実績はありません。期間を変更するか、学習実績を記録してください。</p>');}catch(e){$('analysis-results').innerHTML=`<p role="alert">${esc(e.message)}</p>`;}
}
